	'mod_modal_text'         => [ 'Kontrola trvá do 24 hodín. Medzitým môžete pridávať autá — inzeráty sa v katalógu zobrazia hneď po schválení profilu.', 'Перевірка займає до 24 годин. А поки можете додати свої авто — оголошення зʼявляться в каталозі одразу після схвалення профілю.' , 'The review takes up to 24 hours. Meanwhile you can add your cars — listings will appear in the catalogue as soon as the profile is approved.', 'Проверка занимает до 24 часов. А пока можете добавить свои авто — объявления появятся в каталоге сразу после одобрения профиля.' ],
	'mod_edits_modal_text'   => [ 'Zmeny sa zobrazia po kontrole administrátorom. Dovtedy vodiči vidia predchádzajúcu verziu.', 'Зміни зʼявляться після перевірки адміністратором. До того водії бачать попередню версію.' , 'Changes will appear after an administrator reviews them. Until then drivers see the previous version.', 'Изменения появятся после проверки администратором. До этого водители видят предыдущую версию.' ],
	'st_draft'               => [ 'Vyplňte a uložte profil flotily — potom ho pošleme na moderáciu a môžete pridávať autá.', 'Заповніть і збережіть профіль флотилії — після цього він піде на модерацію, і ви зможете додавати авто.' , 'Fill in and save the fleet profile — then it goes to moderation and you can add cars.', 'Заполните и сохраните профиль таксопарка — после этого он уйдёт на модерацию, и вы сможете добавлять авто.' ],
	'st_pending'             => [ 'Profil bol odoslaný na moderáciu. Kým ho kontrolujeme, môžete už pridávať inzeráty.', 'Профіль надіслано на модерацію. Поки ми його перевіряємо, ви вже можете додавати оголошення.' , 'The profile has been sent for moderation. While we review it, you can already add listings.', 'Профиль отправлен на модерацию. Пока мы его проверяем, вы уже можете добавлять объявления.' ],
	'st_edits'               => [ 'Zmeny profilu čakajú na moderáciu. Vodiči zatiaľ vidia predchádzajúcu verziu.', 'Зміни профілю на модерації. До схвалення водії бачать попередню версію.' , 'Profile changes are awaiting moderation. Until approved, drivers see the previous version.', 'Изменения профиля на модерации. До одобрения водители видят предыдущую версию.' ],
	'st_rejected'            => [ 'Profil neprešiel moderáciou. Kontaktujte podporu.', 'Профіль не пройшов модерацію. Зверніться в підтримку.' , 'The profile did not pass moderation. Please contact support.', 'Профиль не прошёл модерацию. Обратитесь в поддержку.' ],
	'st_blocked'             => [ 'Profil bol zablokovaný administrátorom. Vaše inzeráty sú skryté z katalógu.', 'Профіль заблоковано адміністратором. Ваші оголошення приховані з каталогу.' , 'The profile has been blocked by an administrator. Your listings are hidden from the catalogue.', 'Профиль заблокирован администратором. Ваши объявления скрыты из каталога.' ],
